import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';

@Injectable({ providedIn: 'root' })
export class ApiService {
    private baseUrl = '/api';

    constructor(private http: HttpClient) { }

    // Authentification
    login(credentials: { Email: string; Password: string }) {
        return this.http.post<{ token: string }>(
            `${this.baseUrl}/authentification`, credentials
        );
    }

    // Utilisateur connecté via token
    getUser() {
        return this.http.get<any>(`${this.baseUrl}/user`);
    }

    updateUser(data: any) {
        return this.http.post(`${this.baseUrl}/user/update`, data);
    }

    deleteUser() {
        return this.http.delete(`${this.baseUrl}/user`);
    }

    // Équipes
    getAllTeams() {
        return this.http.get<any[]>(`${this.baseUrl}/team`);
    }

    createTeam(data: any) {
        return this.http.post(`${this.baseUrl}/team`, data);
    }

    updateTeam(id: string, data: any) {
        return this.http.put(`${this.baseUrl}/team/${id}`, data);
    }

    deleteTeam(id: string) {
        return this.http.delete(`${this.baseUrl}/team/${id}`);
    }

    postPresence(data: { Type: string; Timestamp: string }) {
        return this.http.post(`${this.baseUrl}/presence/create`, data);
    }
}

import { Component, OnInit } from '@angular/core';
import { Router } from '@angular/router';
import { CommonModule } from '@angular/common';
import { ApiService } from '../../../services/api.service';

@Component({
  selector: 'app-home',
  standalone: true,
  imports: [CommonModule],
  template: `
  <section class="dashboard">
    <header class="dashboard-header">
      <h1>Tableau de bord</h1>
      <p>Gestion du temps et suivi des présences</p>
    </header>

    <div class="dashboard-cards">
      <!-- Profil -->
      <div class="card">
        <h2>Profil</h2>
        <p>Accédez à vos informations personnelles et à vos paramètres.</p>
        <button (click)="goToProfile()">Voir le profil</button>
      </div>

      <!-- Équipes -->
      <div class="card">
        <h2>Équipes</h2>
        <p>Gérez vos équipes et visualisez les membres.</p>
        <button (click)="goToTeams()">Gérer les équipes</button>
      </div>

      <!-- Présence -->
      <div class="card">
        <h2>Présence</h2>
        <p>Enregistrez votre présence quotidienne.</p>
        <button (click)="pointer()">Pointer</button>
        <p *ngIf="message" class="message">{{ message }}</p>
      </div>
    </div>
  </section>
  `,
  styleUrls: ['./home.component.css']
})
export class HomeComponent implements OnInit {
  message: string | null = null;

  constructor(private router: Router, private apiService: ApiService) { }

  ngOnInit() {
    const token = localStorage.getItem('access_token');
    const userId = localStorage.getItem('user_id');
    if (!token || !userId) {
      console.warn('Token ou ID utilisateur manquant.');
    }
  }

  goToProfile() { this.router.navigate(['/profile']); }
  goToTeams() { this.router.navigate(['/teams']); }

  pointer() {
    const userId = localStorage.getItem('user_id');
    if (!userId) {
      this.message = "❌ Impossible de pointer : utilisateur non identifié.";
      return;
    }

    const presenceData = {
      Type: "Work",
      Timestamp: new Date().toISOString(),
      User: userId
    };

    console.log("Envoi des données de présence :", presenceData);

    this.apiService.postPresence(presenceData).subscribe({
      next: () => {
        this.message = "✅ Présence enregistrée avec succès.";
        setTimeout(() => this.message = null, 3000);
      },
      error: (err: any) => {
        console.error("❌ Erreur lors de l'enregistrement :", err);
        this.message = "Erreur lors de l'enregistrement.";
        setTimeout(() => this.message = null, 3000);
      }
    });
  }
}

import { Component } from '@angular/core';
import { Router } from '@angular/router';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { ApiService } from '../../../services/api.service';

@Component({
  selector: 'app-login',
  standalone: true,
  imports: [CommonModule, FormsModule],
  styleUrls: ['./login.component.css'],
  template: `
  <div class="login-container">
    <div class="login-card">
      <h1>Connexion</h1>
      <form (ngSubmit)="onLogin()" #f="ngForm">
        <label>Email</label>
        <input name="email" type="email" [(ngModel)]="email" placeholder="Votre email" required>
        <label>Mot de passe</label>
        <input name="password" type="password" [(ngModel)]="password" placeholder="Votre mot de passe" required>
        <button class="primary" type="submit" [disabled]="loading || !f.form.valid">
          {{ loading ? 'Connexion...' : 'Se connecter' }}
        </button>
        <div class="error" *ngIf="error">{{ error }}</div>
      </form>
    </div>
  </div>
  `
})
export class LoginComponent {
  email = '';
  password = '';
  loading = false;
  error = '';

  constructor(private router: Router, private api: ApiService) { }

  onLogin() {
    if (this.loading) return;
    this.error = '';
    this.loading = true;

    this.api.login({ Email: this.email, Password: this.password }).subscribe({
      next: (res: any) => {
        // Stockage du token
        if (!res.Token || !res._id) {
          this.error = 'Réponse du serveur invalide.';
          this.loading = false;
          return;
        }

        localStorage.setItem('access_token', res.Token);
        localStorage.setItem('user_id', res._id); //stocke l'ID utilisateur

        this.router.navigate(['/home']);
      },
      error: (err) => {
        this.error = err?.error?.message || 'Identifiants invalides.';
        this.loading = false;
      }
    });
  }
}

import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { ApiService } from '../../../services/api.service';
import { Router } from '@angular/router';

interface UserProfile {
  firstName: string;
  lastName: string;
  password?: string;
  role: string;
  team: string;
}

@Component({
  selector: 'app-profile',
  standalone: true,
  imports: [CommonModule, FormsModule],
  styleUrls: ['./profile.component.css'],
  template: `
    <div class="profile-container">
      <div class="profile-card">
        <div class="profile-header">
          <h1>Mon Profil</h1>

          <div class="profile-actions">
            <button
              class="btn btn-secondary"
              (click)="toggleEditMode()"
              [disabled]="isLoading"
            >
              {{ isEditMode ? 'Annuler' : 'Modifier' }}
            </button>

            <button
              class="btn btn-danger"
              (click)="confirmDelete()"
              [disabled]="isLoading"
            >
              Supprimer le compte
            </button>
          </div>
        </div>

        <div class="profile-content">
          <!-- Vue profil -->
          <div *ngIf="!isEditMode" class="profile-view">
            <div class="profile-info">
              <div>
                <label>Prénom :</label>
                <span>{{ userProfile.firstName }}</span>
              </div>

              <div>
                <label>Nom :</label>
                <span>{{ userProfile.lastName }}</span>
              </div>

              <div>
                <label>Rôle :</label>
                <span>{{ userProfile.role }}</span>
              </div>

              <div>
                <label>Équipe :</label>
                <span>{{ userProfile.team || 'Aucune' }}</span>
              </div>
            </div>
          </div>

          <!-- Formulaire d’édition -->
          <form *ngIf="isEditMode" class="profile-edit" (ngSubmit)="updateProfile()">
            <div>
              <label>Prénom *</label>
              <input [(ngModel)]="editProfile.firstName" name="firstName" required />
            </div>

            <div>
              <label>Nom *</label>
              <input [(ngModel)]="editProfile.lastName" name="lastName" required />
            </div>

            <div>
              <label>Mot de passe *</label>
              <input [(ngModel)]="editProfile.password" name="password" type="password" required />
            </div>

            <div class="profile-actions">
              <button type="submit" class="primary" [disabled]="isLoading">
                {{ isLoading ? 'Sauvegarde...' : 'Sauvegarder' }}
              </button>

              <button type="button" class="secondary" (click)="toggleEditMode()" [disabled]="isLoading">
                Annuler
              </button>
            </div>
          </form>

          <div *ngIf="message" [ngClass]="messageType">
            {{ message }}
          </div>
        </div>

        <!-- Modal de suppression -->
        <div *ngIf="showDeleteModal" class="modal-overlay" (click)="cancelDelete()">
          <div class="modal" (click)="$event.stopPropagation()">
            <h3>Confirmer la suppression</h3>
            <p>Êtes-vous sûr de vouloir supprimer votre compte ?</p>

            <button (click)="deleteProfile()" [disabled]="isLoading">
              {{ isLoading ? 'Suppression...' : 'Supprimer définitivement' }}
            </button>

            <button (click)="cancelDelete()" [disabled]="isLoading">
              Annuler
            </button>
          </div>
        </div>
      </div>
    </div>
  `
})
export class ProfileComponent implements OnInit {
  userProfile: UserProfile = {
    firstName: '',
    lastName: '',
    password: '',
    role: '',
    team: ''
  };

  editProfile: UserProfile = { ...this.userProfile };
  isEditMode = false;
  isLoading = false;
  message = '';
  messageType: 'success' | 'error' = 'success';
  showDeleteModal = false;

  constructor(private apiService: ApiService, private router: Router) { }

  ngOnInit() {
    const token = localStorage.getItem('access_token');
    if (!token) {
      this.router.navigate(['/login']);
      return;
    }

    this.loadProfile();
  }

  loadProfile() {
    this.isLoading = true;
    this.apiService.getUser().subscribe({
      next: (res: any) => {
        const u = res.user || {};
        this.userProfile = {
          firstName: u.FirstName || '',
          lastName: u.LastName || '',
          role: u.Role || '',
          team: u.Team || ''
        };
        this.editProfile = { ...this.userProfile, password: '' };
        this.isLoading = false;
      },
      error: () => {
        this.showMessage('Impossible de charger le profil.', 'error');
        this.isLoading = false;
      }
    });
  }

  toggleEditMode() {
    this.isEditMode = !this.isEditMode;
    if (this.isEditMode) this.editProfile = { ...this.userProfile, password: '' };
    this.clearMessage();
  }

  updateProfile() {
    this.isLoading = true;

    const updateData = {
      FirstName: this.editProfile.firstName,
      LastName: this.editProfile.lastName,
      Password: this.editProfile.password,
      Role: this.userProfile.role,
      Team: this.userProfile.team
    };

    this.apiService.updateUser(updateData).subscribe({
      next: () => {
        this.userProfile = { ...this.editProfile };
        this.isEditMode = false;
        this.isLoading = false;
        this.showMessage('Profil mis à jour avec succès !', 'success');
      },
      error: (err) => {
        this.isLoading = false;
        console.error('Erreur update', err);
        this.showMessage('Erreur lors de la mise à jour.', 'error');
      }
    });
  }

  confirmDelete() { this.showDeleteModal = true; }
  cancelDelete() { this.showDeleteModal = false; }

  deleteProfile() {
    this.isLoading = true;
    this.apiService.deleteUser().subscribe({
      next: () => {
        this.isLoading = false;
        this.showDeleteModal = false;
        localStorage.removeItem('access_token');
        this.router.navigate(['/login']);
      },
      error: () => {
        this.isLoading = false;
        this.showDeleteModal = false;
        this.showMessage('Impossible de supprimer le profil.', 'error');
      }
    });
  }

  private showMessage(text: string, type: 'success' | 'error') {
    this.message = text;
    this.messageType = type;
    setTimeout(() => this.clearMessage(), 5000);
  }

  private clearMessage() { this.message = ''; }
}

import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { ApiService } from '../../../services/api.service';

interface Team {
  _id: string;
  name: string;
  users?: any[];
  editing?: boolean;
}

@Component({
  selector: 'app-teams',
  standalone: true,
  imports: [CommonModule, FormsModule],
  template: `
  <section class="teams">
    <h1>Gestion des équipes</h1>

    <!-- Formulaire de création -->
    <form (ngSubmit)="createTeam()" #teamForm="ngForm">
      <input
        type="text"
        placeholder="Nom de l'équipe"
        name="name"
        [(ngModel)]="newTeamName"
        required
      />
      <button type="submit" [disabled]="!teamForm.valid">Ajouter</button>
    </form>

    <hr>

    <!-- Liste des équipes -->
    <ul>
      <li *ngFor="let team of teams">
        <div *ngIf="!team.editing">
          <strong>{{ team.name }}</strong> ({{ team.users?.length || 0 }} membres)
          <button (click)="enableEdit(team)">✏️ Modifier</button>
          <button (click)="deleteTeam(team._id)">🗑️ Supprimer</button>
        </div>

        <div *ngIf="team.editing">
          <input [(ngModel)]="team.name" name="editName" />
          <button (click)="updateTeam(team)">💾 Sauvegarder</button>
          <button (click)="cancelEdit(team)">❌ Annuler</button>
        </div>
      </li>
    </ul>
  </section>
  `,
  styleUrls: ['./teams.components.css']
})
export class TeamsComponent implements OnInit {
  teams: Team[] = [];
  newTeamName = '';

  constructor(private apiService: ApiService) { }

  ngOnInit() {
    this.loadTeams();
  }

  loadTeams() {
    this.apiService.getAllTeams().subscribe({
      next: (res: any) => this.teams = res,
      error: (err) => console.error('Erreur chargement équipes:', err)
    });
  }

  createTeam() {
    const data = { name: this.newTeamName, users: [] };
    this.apiService.createTeam(data).subscribe({
      next: (res: any) => {
        this.teams.push(res);
        this.newTeamName = '';
      },
      error: (err) => console.error('Erreur création équipe:', err)
    });
  }

  enableEdit(team: Team) {
    team.editing = true;
  }

  cancelEdit(team: Team) {
    team.editing = false;
    this.loadTeams();
  }

  updateTeam(team: Team) {
    const data = { name: team.name, users: team.users || [] };
    this.apiService.updateTeam(team._id, data).subscribe({
      next: () => { team.editing = false; this.loadTeams(); },
      error: (err) => console.error('Erreur mise à jour équipe:', err)
    });
  }

  deleteTeam(id: string) {
    if (!confirm('Supprimer cette équipe ?')) return;
    this.apiService.deleteTeam(id).subscribe({
      next: () => this.teams = this.teams.filter(t => t._id !== id),
      error: (err) => console.error('Erreur suppression équipe:', err)
    });
  }
}
